package com.anamcara.controller;
import com.anamcara.model.Appointment;import com.anamcara.repository.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.util.Map;
@RestController @RequestMapping("/api/admin/appointments")public class AdminAppointmentController{private final AppointmentRepository repository;public AdminAppointmentController(AppointmentRepository repository){this.repository=repository;}@PostMapping public Appointment create(@RequestBody Appointment a){validate(a);a.paymentMethod="Manual / offline booking";a.paymentReference="MANUAL";Appointment saved=repository.save(a);return repository.updateStatus(saved.id,"CONFIRMED");}@PutMapping("/{id}")public Appointment update(@PathVariable String id,@RequestBody Appointment a){validate(a);return repository.update(id,a);}private void validate(Appointment a){if(blank(a.name)||blank(a.phone)||blank(a.service)||blank(a.appointmentMode)||blank(a.preferredDate)||blank(a.preferredTime))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Name, phone, service, mode, date and time are required.");if(a.paymentAmount<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Payment amount cannot be negative.");try{LocalTime time=LocalTime.parse(a.preferredTime);LocalDate.parse(a.preferredDate);if((time.getMinute()!=0&&time.getMinute()!=30)||time.isBefore(LocalTime.of(10,0))||time.isAfter(LocalTime.of(18,0)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a half-hour slot between 10:00 and 18:00.");}catch(DateTimeException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"The appointment date or time is invalid.");}}private boolean blank(String v){return v==null||v.isBlank();}@ExceptionHandler(SlotUnavailableException.class)@ResponseStatus(HttpStatus.CONFLICT)public Map<String,String>unavailable(SlotUnavailableException e){return Map.of("message",e.getMessage());}}
